syntax:
// the shape of every recursive function
returnType name(parameters) {
    if (simplest case) {          // BASE CASE: answer directly, no call to itself
        return answer;
    }
    // RECURSIVE CASE: call yourself with a SMALLER problem
    return something + name(smaller problem);
}

// example: factorial
long long factorial(int n) {
    if (n <= 1)                   // base case
        return 1;
    return n * factorial(n - 1);  // recursive case
}

