#include <iostream>
using namespace std;

void countdown(int n) {
    if (n == 0) {
        cout << "Go!" << endl;
        return;
    }
    cout << n << " ";
    countdown(n - 1);
}

int main() {
    countdown(2);
    return 0;
}

#include <iostream>
using namespace std;

long long factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

long long factorialLoop(int n) {
    long long result = 1;
    for (int i = 2; i <= n; i++) {
        result = result * i;
    }
    return result;
}

int main() {
    cout << "recursive: " << factorial(4) << endl;
    cout << "loop:      " << factorialLoop(4) << endl;
    return 0;
}

#include <iostream>
using namespace std;

void show(int n) {
    if (n == 0) return;
    cout << "in " << n << endl;
    show(n - 1);
    cout << "out " << n << endl;
}

int main() {
    show(3);
    return 0;
}

